SELECT 't_driver_daily_snapshot' AS tbl, COUNT(*) AS cnt FROM t_driver_daily_snapshot WHERE snapshot_date = '2026-07-29'
UNION ALL SELECT 't_recall_list(清空,待管道产出)', COUNT(*) FROM t_recall_list WHERE data_date = '2026-07-29'
